-- ══════════════════════════════════════════════════════════════
-- PASSO 4: Tarefas (15 registros)
-- ══════════════════════════════════════════════════════════════
-- TAREFAS — 15 registros
ON CONFLICT (id) DO NOTHING;

SELECT count(*) || ' tarefas importadas' AS resultado FROM public.tarefas;

-- ══════════════════════════════════════════════════════════════
-- PASSO 5: Atividades (62 registros)
-- ══════════════════════════════════════════════════════════════
-- ATIVIDADES — 62 registros
ON CONFLICT (id) DO NOTHING;

SELECT count(*) || ' atividades importadas' AS resultado FROM public.atividades;
